"""# Nova seção"""

def pseudo_estado_estacionario_ER_Xa(
    dados,
    label,
    CA0,
    CB0,
    Ccat=0.26,
    guess=(0.001, 1.0),
    incerteza_Keq=0.15
):

    t_exp = dados[:, 0]   # minutos
    Xa_exp = dados[:, 1]

    # ============================================================
    # 1. ESTIMATIVA DO EQUILÍBRIO EXPERIMENTAL
    # ============================================================

    Xa_eq = Xa_exp[-1]

    CA_eq = CA0 * (1 - Xa_eq)
    CB_eq = CB0 - CA0 * Xa_eq
    CE_eq = CA0 * Xa_eq
    CW_eq = CE_eq

    # K_eq calculado com concentrações
    Keq = (CE_eq * CW_eq) / (CA_eq * CB_eq)

    print(f"\n{'='*65}")
    print(f"{label}")
    print(f"{'='*65}")
    print(f"Keq (concentração, ponto final) = {Keq:.6f}")

    # ============================================================
    # 2. MODELO REDUZIDO
    # ============================================================

    def model(t, X, kd, K_W, Keq_model):

        Xa = X[0]

        CA = CA0 * (1 - Xa)
        CB = CB0 - CA0 * Xa
        CE = CA0 * Xa
        CW = CE

        # Termo de adsorção da água
        denom = 1 + K_W * CW

        # Velocidade da reação
        ra = kd * (
            (CA * CB)
            - (CE * CW) / Keq_model
        ) / denom

        dXadt = ra / CA0

        return [dXadt]

    # ============================================================
    # 3. FUNÇÃO DE AJUSTE
    # ============================================================

    def ajustar_parametros(Keq_model, guess_parametros):

        def objective(params):

            kd, K_W = params

            sol = solve_ivp(
                model,
                [0, max(t_exp)],
                [0.0],
                args=(kd, K_W, Keq_model),
                t_eval=t_exp
            )

            # Caso o solver não tenha convergido corretamente
            if not sol.success:
                return 1e10

            Xa_model = sol.y[0]

            # RMSE
            rmse = np.sqrt(
                np.mean((Xa_model - Xa_exp) ** 2)
            )

            return rmse

        bounds = [
            (1e-6, 10),   # kd
            (1e-6, 10)    # K_W
        ]

        result = minimize(
            objective,
            guess_parametros,
            bounds=bounds,
            method='L-BFGS-B'
        )

        kd, K_W = result.x

        return kd, K_W, result.fun

    # ============================================================
    # 4. AJUSTE CENTRAL
    # ============================================================

    kd, K_W, rmse = ajustar_parametros(
        Keq,
        guess
    )

    print("\nParâmetros ajustados para o Keq central:")
    print(f"kd   = {kd:.6f}")
    print(f"K_W  = {K_W:.6f}")
    print(f"RMSE = {rmse:.6f}")

    # ============================================================
    # 5. PROPAGAÇÃO DA INCERTEZA DE ±15% NO K_eq
    # ============================================================

    Keq_menos = Keq * (1 - incerteza_Keq)
    Keq_mais = Keq * (1 + incerteza_Keq)

    print("\nPropagação da incerteza de K_eq:")
    print(f"Keq central = {Keq:.6f}")
    print(f"Keq -15%    = {Keq_menos:.6f}")
    print(f"Keq +15%    = {Keq_mais:.6f}")

    # ------------------------------------------------------------
    # Ajuste para Keq -15%
    # ------------------------------------------------------------

    kd_menos, KW_menos, rmse_menos = ajustar_parametros(
        Keq_menos,
        (kd, K_W)
    )

    # ------------------------------------------------------------
    # Ajuste para Keq +15%
    # ------------------------------------------------------------

    kd_mais, KW_mais, rmse_mais = ajustar_parametros(
        Keq_mais,
        (kd, K_W)
    )

    # ============================================================
    # 6. INTERVALOS PROPAGADOS
    # ============================================================

    kd_min = min(kd_menos, kd, kd_mais)
    kd_max = max(kd_menos, kd, kd_mais)

    KW_min = min(KW_menos, K_W, KW_mais)
    KW_max = max(KW_menos, K_W, KW_mais)

    print("\nIntervalos obtidos pela propagação de ±15% em K_eq:")
    print(
        f"kd   = {kd:.6f} "
        f"[{kd_min:.6f} ; {kd_max:.6f}]"
    )

    print(
        f"K_W  = {K_W:.6f} "
        f"[{KW_min:.6f} ; {KW_max:.6f}]"
    )

    # ============================================================
    # 7. SIMULAÇÃO FINAL COM O K_eq CENTRAL
    # ============================================================

    t_sim = np.linspace(
        0,
        max(t_exp),
        300
    )

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        [0.0],
        args=(kd, K_W, Keq),
        t_eval=t_sim
    )

    Xa_sim = sol.y[0]

    CE_sim = CA0 * Xa_sim

    # ============================================================
    # 8. R²
    # ============================================================

    Xa_model_exp = np.interp(
        t_exp,
        t_sim,
        Xa_sim
    )

    r2 = r2_score(
        Xa_exp,
        Xa_model_exp
    )

    # ============================================================
    # 9. GRÁFICO
    # ============================================================

    plt.figure(figsize=(10, 6))

    plt.plot(
        t_sim,
        Xa_sim,
        label='Xa (simulated)',
        linewidth=2
    )

    plt.scatter(
        t_exp,
        Xa_exp,
        color='red',
        label='Xa (experimental)',
        zorder=5
    )

    plt.xlabel('Time (min)')
    plt.ylabel('Conversion')

    plt.title(
        f'{label}\n'
        f'kd = {kd:.6f} '
        f'[{kd_min:.6f}, {kd_max:.6f}] | '
        f'K_W = {K_W:.4f} '
        f'[{KW_min:.4f}, {KW_max:.4f}]\n'
        f'K_eq = {Keq:.6f} ± {incerteza_Keq*100:.0f}% | '
        f'R² = {r2:.4f}'
    )

    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    # ============================================================
    # 10. RESUMO DOS RESULTADOS
    # ============================================================

    print("\nResumo:")
    print("-" * 65)

    print(f"K_eq central : {Keq:.6f}")
    print(
        f"K_eq range  : "
        f"{Keq_menos:.6f} – {Keq_mais:.6f}"
    )

    print(
        f"kd          : "
        f"{kd:.6f} "
        f"[{kd_min:.6f} – {kd_max:.6f}]"
    )

    print(
        f"K_W         : "
        f"{K_W:.6f} "
        f"[{KW_min:.6f} – {KW_max:.6f}]"
    )

    print(f"R²          : {r2:.4f}")
    print(f"RMSE        : {rmse:.6f}")

    print("-" * 65)

    # ============================================================
    # 11. RETORNO
    # ============================================================

    return (
        t_sim,
        Xa_sim,
        CE_sim,
        kd,
        Keq,
        K_W,
        r2,
        rmse,
        kd_min,
        kd_max,
        KW_min,
        KW_max,
        Keq_menos,
        Keq_mais
    )



import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import minimize
from sklearn.metrics import r2_score
import matplotlib.pyplot as plt

def pseudo_estado_estacionario_ER_multi(
    dados, label, CA0, CB0,
    Ccat=0.26,
    guess=(0.001, 1.0),
    salvar_video=True,
    nome_video='reacao.mp4'
):

    import numpy as np
    import matplotlib.pyplot as plt
    from scipy.integrate import solve_ivp
    from scipy.optimize import minimize
    from sklearn.metrics import r2_score
    from matplotlib.animation import FuncAnimation

    # ===== Dados experimentais =====
    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    CA_exp = CA0 * (1 - Xa_exp)
    CB_exp = CB0 - CA0 * Xa_exp
    CE_exp = CA0 * Xa_exp
    CW_exp = CE_exp

    C0 = [CA0, CB0, 0.0, 0.0]

    # ===== Keq experimental =====
    CE_eq = CE_exp[-1]
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = (CE_eq * CE_eq) / (CA_eq * CB_eq)

    print(f"Keq = {Keq:.6f}")

    # ===== Modelo cinético =====
    def model(t, C, kd, K_W, Keq):
        CA, CB, CE, CW = C
        denom = (1 + K_W * CW)
        ra = kd * ((CA * CB) - (CE * CW) / Keq) / denom
        return [-ra, -ra, ra, ra]

    # ===== Função objetivo COM penalização =====
    def objective(params):
        kd, K_W = params

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, K_W, Keq),
            t_eval=t_exp
        )

        if not sol.success:
            return 1e6

        CA_m, CB_m, CE_m, CW_m = sol.y

        erro_dados = (
            np.mean((CA_m - CA_exp) ** 2) +
            np.mean((CB_m - CB_exp) ** 2) +
            np.mean((CE_m - CE_exp) ** 2) +
            np.mean((CW_m - CW_exp) ** 2)
        )

        # ===== Penalização de balanço =====
        penal = (
            np.mean((CA_m + CE_m - CA0)**2) +
            np.mean((CB_m + CE_m - CB0)**2) +
            np.mean((CE_m - CW_m)**2)
        )

        return np.sqrt(erro_dados + penal)

    # ===== Otimização =====
    bounds = [(1e-6, 10), (1e-6, 10)]

    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')

    kd, K_W = result.x

    print(f"kd={kd:.6f}, K_W={K_W:.4f}")

    # ===== Simulação final =====
    t_sim = np.linspace(0, max(t_exp), 300)

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, K_W, Keq),
        t_eval=t_sim
    )

    CA_sim, CB_sim, CE_sim, CW_sim = sol.y
    Xa_sim = (CA0 - CA_sim) / CA0

    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, CE_sim))

    print(f"R² = {r2:.4f}")

    # ===== CHECAGEM DE BALANÇO =====
    erro_A = CA_sim + CE_sim - CA0
    erro_B = CB_sim + CE_sim - CB0
    erro_prod = CE_sim - CW_sim

    print("\n=== Verificação de balanço material ===")
    print(f"Erro máximo (A): {np.max(np.abs(erro_A)):.6e}")
    print(f"Erro máximo (B): {np.max(np.abs(erro_B)):.6e}")
    print(f"Erro máximo (Produtos): {np.max(np.abs(erro_prod)):.6e}")

    # ===== Plot do balanço =====
    plt.figure(figsize=(8,5))
    plt.plot(t_sim, erro_A, label='A: CA + CE - CA0')
    plt.plot(t_sim, erro_B, label='B: CB + CE - CB0')
    plt.plot(t_sim, erro_prod, label='CE - CW')

    plt.axhline(0, linestyle='--')
    plt.xlabel('Tempo (min)')
    plt.ylabel('Erro (mol/L)')
    plt.title('Verificação do balanço material')
    plt.legend()
    plt.grid()
    plt.show()

    # ===== ANIMAÇÃO =====
    fig, ax = plt.subplots(figsize=(10, 6))

    line_CA, = ax.plot([], [], '--', label='CA')
    line_CB, = ax.plot([], [], '--', label='CB')
    line_CE, = ax.plot([], [], '-', linewidth=2, label='CE')

    ponto, = ax.plot([], [], 'ro')

    ax.scatter(t_exp, CE_exp, label='CE exp', zorder=5)
    ax.scatter(t_exp, CA_exp, marker='x', label='CA exp')
    ax.scatter(t_exp, CB_exp, marker='x', label='CB exp')

    ax.set_xlim(0, max(t_sim))
    ax.set_ylim(0, max(max(CA_sim), max(CB_sim), max(CE_sim)) * 1.1)

    ax.set_xlabel('Tempo (min)')
    ax.set_ylabel('Concentração (mol/L)')
    ax.set_title(f'{label}\nkd={kd:.4f}, K_W={K_W:.3f}, R²={r2:.4f}')
    ax.legend()
    ax.grid()

    def update(frame):
        line_CA.set_data(t_sim[:frame], CA_sim[:frame])
        line_CB.set_data(t_sim[:frame], CB_sim[:frame])
        line_CE.set_data(t_sim[:frame], CE_sim[:frame])
        ponto.set_data(t_sim[frame], CE_sim[frame])
        return line_CA, line_CB, line_CE, ponto

    ani = FuncAnimation(
        fig,
        update,
        frames=len(t_sim),
        interval=30,
        blit=True
    )

    # ===== SALVAR =====
    if salvar_video:
        try:
            ani.save(nome_video, fps=30)
            print(f"Vídeo salvo como: {nome_video}")
        except:
            print("Erro ao salvar MP4. Tentando GIF...")
            ani.save(nome_video.replace('.mp4', '.gif'), writer='pillow')

    plt.show()

    return t_sim, CE_sim, Xa_sim, kd, Keq, K_W, r2

def pseudo_estado_estacionario_ER_multi(
    dados, label, CA0, CB0,
    Ccat=0.26,
    guess=(0.001, 1.0),
    salvar_video=True,
    nome_video='reacao.mp4'
):

    import numpy as np
    import matplotlib.pyplot as plt
    from scipy.integrate import solve_ivp
    from scipy.optimize import minimize
    from sklearn.metrics import r2_score
    from matplotlib.animation import FuncAnimation

    # ===== Dados experimentais =====
    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    CA_exp = CA0 * (1 - Xa_exp)
    CB_exp = CA0 * (CB0/CA0 - Xa_exp)
    CE_exp = CA0 * Xa_exp
    CW_exp = CE_exp

    C0 = [CA0, CB0, 0.0, 0.0]

    # ===== Keq experimental =====
    CE_eq = CE_exp[-1]
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = (CE_eq * CE_eq) / (CA_eq * CB_eq)

    print(f"Keq = {Keq:.6f}")

    # ===== Modelo cinético =====
    def model(t, C, kd, K_W, Keq):
        CA, CB, CE, CW = C
        denom = (1 + K_W * CW)
        ra = kd * ((CA * CB) - (CE * CW) / Keq) / denom
        return [-ra, -ra, ra, ra]

    # ===== Função objetivo =====
    def objective(params):
        kd, K_W = params

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, K_W, Keq),
            t_eval=t_exp
        )

        if not sol.success:
            return 1e6

        CA_m, CB_m, CE_m, CW_m = sol.y

        erro = (
            np.mean((CA_m - CA_exp) ** 2) +
            np.mean((CB_m - CB_exp) ** 2) +
            np.mean((CE_m - CE_exp) ** 2) +
            np.mean((CW_m - CW_exp) ** 2)
        )

        return np.sqrt(erro)

    # ===== Otimização =====
    bounds = [(1e-6, 10), (1e-6, 10)]

    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')

    kd, K_W = result.x

    print(f"kd={kd:.6f}, K_W={K_W:.4f}")

    # ===== Simulação final =====
    t_sim = np.linspace(0, max(t_exp), 300)

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, K_W, Keq),
        t_eval=t_sim
    )

    CA_sim, CB_sim, CE_sim, CW_sim = sol.y
    Xa_sim = (CA0 - CA_sim) / CA0

    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, CE_sim))

    print(f"R² = {r2:.4f}")

    # ===== ANIMAÇÃO =====
    fig, ax = plt.subplots(figsize=(10, 6))

    line_CA, = ax.plot([], [], '--', label='CA')
    line_CB, = ax.plot([], [], '--', label='CB')
    line_CE, = ax.plot([], [], '-', linewidth=2, label='CE')

    ponto, = ax.plot([], [], 'ro')

    ax.scatter(t_exp, CE_exp, label='CE exp', zorder=5)
    ax.scatter(t_exp, CA_exp, marker='x', label='CA exp')
    ax.scatter(t_exp, CB_exp, marker='x', label='CB exp')

    ax.set_xlim(0, max(t_sim))
    ax.set_ylim(0, max(max(CA_sim), max(CB_sim), max(CE_sim)) * 1.1)

    ax.set_xlabel('Tempo (min)')
    ax.set_ylabel('Concentração (mol/L)')
    ax.set_title(f'{label}\nkd={kd:.4f}, K_W={K_W:.3f}, R²={r2:.4f}')
    ax.legend()
    ax.grid()

    def update(frame):
        line_CA.set_data(t_sim[:frame], CA_sim[:frame])
        line_CB.set_data(t_sim[:frame], CB_sim[:frame])
        line_CE.set_data(t_sim[:frame], CE_sim[:frame])

        ponto.set_data(t_sim[frame], CE_sim[frame])

        return line_CA, line_CB, line_CE, ponto

    ani = FuncAnimation(
        fig,
        update,
        frames=len(t_sim),
        interval=30,
        blit=True
    )

    # ===== SALVAR AUTOMATICAMENTE =====
    if salvar_video:
        try:
            ani.save(nome_video, fps=30)
            print(f"Vídeo salvo como: {nome_video}")
        except:
            print("Erro ao salvar MP4. Tentando GIF...")
            ani.save(nome_video.replace('.mp4', '.gif'), writer='pillow')

    plt.show()

    return t_sim, CE_sim, Xa_sim, kd, Keq, K_W, r2

def pseudo_estado_estacionario_ER_multi(
    dados, label, CA0, CB0,
    Ccat=0.26,
    guess=(0.001, 1.0),
    salvar_video=True,
    nome_video='reacao.mp4'
):

    import numpy as np
    import matplotlib.pyplot as plt
    from scipy.integrate import solve_ivp
    from scipy.optimize import minimize
    from sklearn.metrics import r2_score
    from matplotlib.animation import FuncAnimation

    # ===== Dados experimentais =====
    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    CA_exp = CA0 * (1 - Xa_exp)
    CB_exp = CB0 - CA0 * Xa_exp
    CE_exp = CA0 * Xa_exp
    CW_exp = CE_exp

    C0 = [CA0, CB0, 0.0, 0.0]

    # ===== Keq =====
    CE_eq = CE_exp[-1]
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = (CE_eq * CE_eq) / (CA_eq * CB_eq)

    print(f"Keq = {Keq:.6f}")

    # ===== Modelo =====
    def model(t, C, kd, K_W, Keq):
        CA, CB, CE, CW = C
        denom = (1 + K_W * CW)
        ra = kd * ((CA * CB) - (CE * CW) / Keq) / denom
        return [-ra, -ra, ra, ra]

    # ===== Função objetivo =====
    def objective(params):
        kd, K_W = params

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, K_W, Keq),
            t_eval=t_exp
        )

        if not sol.success:
            return 1e6

        CA_m, CB_m, CE_m, CW_m = sol.y

        erro = (
            np.mean((CA_m - CA_exp) ** 2) +
            np.mean((CB_m - CB_exp) ** 2) +
            np.mean((CE_m - CE_exp) ** 2) +
            np.mean((CW_m - CW_exp) ** 2)
        )

        return np.sqrt(erro)

    # ===== Otimização =====
    bounds = [(1e-6, 10), (1e-6, 10)]

    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')

    kd, K_W = result.x

    print(f"kd = {kd:.6f}, K_W = {K_W:.4f}")

    # ===== Simulação final =====
    t_sim = np.linspace(0, max(t_exp), 300)

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, K_W, Keq),
        t_eval=t_sim
    )

    CA_sim, CB_sim, CE_sim, CW_sim = sol.y
    Xa_sim = (CA0 - CA_sim) / CA0

    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, CE_sim))

    print(f"R² = {r2:.4f}")

    # ===== FIGURA =====
    fig, ax = plt.subplots(figsize=(10, 6))

    line_CA, = ax.plot([], [], '--', label='CA')
    line_CB, = ax.plot([], [], '--', label='CB')
    line_CE, = ax.plot([], [], '-', linewidth=2, label='CE')
    ponto, = ax.plot([], [], 'ro')

    ax.scatter(t_exp, CE_exp, label='CE exp', zorder=5)
    ax.scatter(t_exp, CA_exp, marker='x', label='CA exp')
    ax.scatter(t_exp, CB_exp, marker='x', label='CB exp')

    ax.set_xlim(0, max(t_sim))
    ax.set_ylim(0, max(np.max(CA_sim), np.max(CB_sim), np.max(CE_sim)) * 1.1)

    ax.set_xlabel('Tempo (min)')
    ax.set_ylabel('Concentração (mol/L)')
    ax.set_title(f'{label}\nkd={kd:.4f}, K_W={K_W:.3f}, R²={r2:.4f}')
    ax.legend()
    ax.grid()

    # ===== ANIMAÇÃO =====
    def update(frame):

        if frame == 0:
            return line_CA, line_CB, line_CE, ponto

        line_CA.set_data(t_sim[:frame], CA_sim[:frame])
        line_CB.set_data(t_sim[:frame], CB_sim[:frame])
        line_CE.set_data(t_sim[:frame], CE_sim[:frame])

        # CORREÇÃO PRINCIPAL (sequência!)
        ponto.set_data([t_sim[frame]], [CE_sim[frame]])

        return line_CA, line_CB, line_CE, ponto

    ani = FuncAnimation(
        fig,
        update,
        frames=len(t_sim),
        interval=30,
        blit=False  # mais estável
    )

    # ===== SALVAR =====
    if salvar_video:
        try:
            ani.save(nome_video, fps=30)
            print(f"Vídeo salvo: {nome_video}")
        except Exception as e:
            print("Erro ao salvar MP4:", e)
            print("Salvando como GIF...")
            ani.save(nome_video.replace('.mp4', '.gif'), writer='pillow')

    plt.show()

    return t_sim, CE_sim, Xa_sim, kd, Keq, K_W, r2

def fracmolar_para_Xa(xE_array, CA0, CB0):
    """
    Converte fração molar de éster (baseada em A+B+E+W ) em conversão do ácido (Xa).
    """
    xE = np.asarray(xE_array, dtype=float)
    Xa = xE * (CA0 + CB0) / CA0
    return Xa

def calcular_conversao(dados_acido):
    """
    Calcula a conversão Xa em relação ao limitante (podendo ser o ácido ou o álcool) e retorna um array [tempo, Xa].

    Parâmetro:
      dados_acido : numpy array de duas colunas [tempo, fração molar ácido]

    Retorno:
      numpy array [tempo, Xa]
    """
    C_A0 = dados_acido[0, 1]  # fração inicial do ácido
    Xa = (C_A0 - dados_acido[:, 1]) / C_A0
    return np.column_stack((dados_acido[:, 0], Xa))

def calc_concentracoes_iniciais(r, M_Acido, M_Alcool, rho_Acido, rho_Alcool, BM):
    """
    Calcula as concentrações iniciais (mol/L) do ácido e do álcool
    para uma dada razão molar r = n_alcool/acido.

    Parâmetros:
    r          : razão molar Alcool:Acido
    M_Acido    : massa molar do ácido (g/mol)
    M_Alcool   : massa molar do álcool (g/mol)
    rho_Acido  : densidade do ácido (g/mL)
    rho_Alcool : densidade do álcool (g/mL)
    BM         : base molar (mol de ácido)

    Retorna:
    (C_Alcool, C_Acido) em mol/L
    """
    # Volume total em litros
    V_total_L = ((r * BM * M_Alcool) / rho_Alcool + (BM * M_Acido) / rho_Acido) / 1000.0   # L


    # Concentrações
    C_Alcool = (r * BM)/ V_total_L     #mol/L
    C_Acido = (BM) / V_total_L   # mol/L

    return C_Alcool, C_Acido

import numpy as np
import matplotlib.pyplot as plt
from scipy.integrate import solve_ivp
from sklearn.metrics import r2_score
import matplotlib.animation as animation


def abc_optimize(objective, bounds, n_bees=40, max_iter=200, limit=50):

    dim = len(bounds)

    food = np.array([
        [np.random.uniform(b[0], b[1]) for b in bounds]
        for _ in range(n_bees)
    ])

    fitness = np.array([objective(x) for x in food])
    trial = np.zeros(n_bees)

    history = []

    best_idx = np.argmin(fitness)
    best = food[best_idx].copy()
    best_fit = fitness[best_idx]

    for it in range(max_iter):

        history.append(food.copy())

        # EMPLOYED BEES
        for i in range(n_bees):

            k = np.random.randint(n_bees)
            while k == i:
                k = np.random.randint(n_bees)

            phi = np.random.uniform(-1,1,dim)
            candidate = food[i] + phi*(food[i]-food[k])

            for d in range(dim):
                candidate[d] = np.clip(candidate[d], bounds[d][0], bounds[d][1])

            f = objective(candidate)

            if f < fitness[i]:
                food[i] = candidate
                fitness[i] = f
                trial[i] = 0
            else:
                trial[i] += 1

        # ONLOOKER BEES
        prob = 1/(1+fitness)
        prob = prob/prob.sum()

        for _ in range(n_bees):

            i = np.random.choice(range(n_bees), p=prob)

            k = np.random.randint(n_bees)
            while k == i:
                k = np.random.randint(n_bees)

            phi = np.random.uniform(-1,1,dim)
            candidate = food[i] + phi*(food[i]-food[k])

            for d in range(dim):
                candidate[d] = np.clip(candidate[d], bounds[d][0], bounds[d][1])

            f = objective(candidate)

            if f < fitness[i]:
                food[i] = candidate
                fitness[i] = f
                trial[i] = 0
            else:
                trial[i] += 1

        # SCOUT BEES
        for i in range(n_bees):

            if trial[i] > limit:

                food[i] = np.array([
                    np.random.uniform(b[0], b[1]) for b in bounds
                ])

                fitness[i] = objective(food[i])
                trial[i] = 0

        best_idx = np.argmin(fitness)

        if fitness[best_idx] < best_fit:
            best_fit = fitness[best_idx]
            best = food[best_idx].copy()

    return best, best_fit, history


def pseudo_estado_estacionario_ER(dados, label, CA0, CB0, video_nome="abc_bees.mp4"):

    t_exp = dados[:,0]
    Xa_exp = dados[:,1]
    CE_exp = Xa_exp * CA0

    C0 = [CA0, CB0, 0, 0]

    CE_eq = CE_exp[-1]
    CW_eq = CE_eq
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq

    Keq = (CE_eq*CW_eq)/(CA_eq*CB_eq)

    print("Keq =", Keq)

    def model(t, C, kd, Kw, Keq):

        CA,CB,CE,CW = C

        ra = kd*((CA*CB)-(CE*CW)/Keq)/(1+Kw*CW)

        return [-ra,-ra,ra,ra]

    def objective(params):

        kd,Kw = params

        try:

            sol = solve_ivp(model,
                            [0,max(t_exp)],
                            C0,
                            args=(kd,Kw,Keq),
                            t_eval=t_exp,
                            method="LSODA")

            CE_model = sol.y[2]

            rmse = np.sqrt(np.mean((CE_model-CE_exp)**2))

            return rmse

        except:
            return 1e10


    bounds=[(1e-6,10),(1e-6,10)]

    best,err,history = abc_optimize(objective,bounds)

    kd,Kw = best

    print("kd =",kd)
    print("Kw =",Kw)

    t_sim = np.linspace(0,max(t_exp),300)

    sol = solve_ivp(model,
                    [0,max(t_exp)],
                    C0,
                    args=(kd,Kw,Keq),
                    t_eval=t_sim,
                    method="LSODA")

    r2 = r2_score(CE_exp,np.interp(t_exp,t_sim,sol.y[2]))

    print("R2 =",r2)

    plt.figure()

    plt.plot(t_sim,sol.y[2],label="Modelo")
    plt.scatter(t_exp,CE_exp,label="Experimental")

    plt.xlabel("Tempo")
    plt.ylabel("CE")
    plt.title(label)
    plt.legend()

    plt.show()

    # -------------------------
    # GERAR VÍDEO DAS ABELHAS
    # -------------------------

    fig, ax = plt.subplots()

    ax.set_xlim(bounds[0][0], bounds[0][1])
    ax.set_ylim(bounds[1][0], bounds[1][1])

    ax.set_xlabel("kd")
    ax.set_ylabel("Kw")

    scatter = ax.scatter([],[])

    def update(frame):

        food = history[frame]

        kd_vals = food[:,0]
        Kw_vals = food[:,1]

        scatter.set_offsets(np.c_[kd_vals,Kw_vals])

        ax.set_title(f"Iteração {frame}")

        return scatter,

    ani = animation.FuncAnimation(
        fig,
        update,
        frames=len(history),
        interval=200,
        blit=True
    )

    ani.save(video_nome, writer="ffmpeg", fps=5)

    plt.close()

    print("Vídeo salvo como:",video_nome)

    return kd,Kw

def pseudo_estado_estacionario_ER_multi(dados, label, CA0, CB0, Ccat=0.26, guess=(0.001, 1.0)):

    # ===== Dados experimentais =====
    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    CA_exp = CA0 * (1 - Xa_exp)
    CB_exp = CA0 * (CB0/CA0 - Xa_exp)
    CE_exp = CA0 * Xa_exp
    CW_exp = CE_exp  # estequiometria

    C0 = [CA0, CB0, 0.0, 0.0]

    # ===== Keq experimental =====
    CE_eq = CE_exp[-1]
    CW_eq = CE_eq
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = (CE_eq * CW_eq) / (CA_eq * CB_eq)

    print(f"Keq (do equilíbrio) = {Keq:.6f}")

    # ===== Modelo cinético =====
    def model(t, C, kd, K_W, Keq):
        CA, CB, CE, CW = C
        denom = (1 + K_W * CW)
        ra = kd * ((CA * CB) - (CE * CW) / Keq) / denom
        return np.array([-ra, -ra, ra, ra])

    # ===== Função objetivo MULTI =====
    def objective(params):
        kd, K_W = params

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, K_W, Keq),
            t_eval=t_exp
        )

        if not sol.success:
            return 1e6

        CA_model, CB_model, CE_model, CW_model = sol.y

        # ===== Erro combinado =====
        erro = (
            np.mean((CA_model - CA_exp) ** 2) +
            np.mean((CB_model - CB_exp) ** 2) +
            np.mean((CE_model - CE_exp) ** 2) +
            np.mean((CW_model - CW_exp) ** 2)
        )

        return np.sqrt(erro)

    # ===== Otimização =====
    bounds = [(1e-6, 10), (1e-6, 10)]

    result = minimize(
        objective,
        guess,
        bounds=bounds,
        method='L-BFGS-B'
    )

    kd, K_W = result.x

    print(f"Parâmetros ajustados: kd={kd:.6f}, K_W={K_W:.4f}")

    # ===== Simulação final =====
    t_sim = np.linspace(0, max(t_exp), 300)

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, K_W, Keq),
        t_eval=t_sim
    )

    CA_sim, CB_sim, CE_sim, CW_sim = sol.y
    Xa_sim = (CA0 - CA_sim) / CA0

    # ===== R² (baseado em CE) =====
    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, CE_sim))

    # ===== Plot =====
    plt.figure(figsize=(10, 6))

    plt.plot(t_sim, CE_sim, label='CE (simulado)', linewidth=2)
    plt.plot(t_sim, CA_sim, label='CA (simulado)', linestyle='--')
    plt.plot(t_sim, CB_sim, label='CB (simulado)', linestyle='--')

    plt.scatter(t_exp, CE_exp, label='CE (exp)', zorder=5)
    plt.scatter(t_exp, CA_exp, label='CA (exp)', marker='x')
    plt.scatter(t_exp, CB_exp, label='CB (exp)', marker='x')

    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'{label}\nkd={kd:.6f}, K_W={K_W:.3f}, R²={r2:.4f}')
    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    return t_sim, CE_sim, Xa_sim, kd, Keq, K_W, r2

from matplotlib.animation import FuncAnimation

def animar_reacao(t_sim, CA_sim, CB_sim, CE_sim, t_exp, CA_exp, CB_exp, CE_exp):

    fig, ax = plt.subplots(figsize=(10, 6))

    # Linhas vazias (serão atualizadas)
    line_CA, = ax.plot([], [], '--', label='CA (simulado)')
    line_CB, = ax.plot([], [], '--', label='CB (simulado)')
    line_CE, = ax.plot([], [], '-', linewidth=2, label='CE (simulado)')

    # Pontos experimentais fixos
    ax.scatter(t_exp, CE_exp, label='CE (exp)', zorder=5)
    ax.scatter(t_exp, CA_exp, marker='x', label='CA (exp)')
    ax.scatter(t_exp, CB_exp, marker='x', label='CB (exp)')

    ax.set_xlim(0, max(t_sim))
    ax.set_ylim(0, max(max(CA_sim), max(CB_sim), max(CE_sim))*1.1)

    ax.set_xlabel('Tempo (min)')
    ax.set_ylabel('Concentração (mol/L)')
    ax.set_title('Evolução da reação ao longo do tempo')
    ax.legend()
    ax.grid()

    # Função que atualiza frame a frame
    def update(frame):
        line_CA.set_data(t_sim[:frame], CA_sim[:frame])
        line_CB.set_data(t_sim[:frame], CB_sim[:frame])
        line_CE.set_data(t_sim[:frame], CE_sim[:frame])
        return line_CA, line_CB, line_CE

    ani = FuncAnimation(
        fig,
        update,
        frames=len(t_sim),
        interval=30,  # velocidade (ms)
        blit=True
    )

    plt.show()

    return ani

def pseudo_estado_estacionario_ER(dados, label, CA0, CB0, Ccat=0.26, guess=(0.001, 1.0)):
    """
    Ajusta kd + K_W usando o modelo de Langmuir-Hinshelwood simplificado
    (K_A, K_B, K_E desprezados).

    Modelo cinético:
    ra = (kd * (CA*CB - CE*CW/Keq)) / (1 + K_W*CW)
    """

    # Extrai dados
    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]
    CE_exp = Xa_exp * CA0

    C0 = [CA0, CB0, 0.0, 0.0]

    # Keq do equilíbrio experimental
    CE_eq = CE_exp[-1]
    CW_eq = CE_eq
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = (CE_eq * CW_eq) / (CA_eq * CB_eq)
    print(f"Keq (do equilíbrio) = {Keq:.6f}")

    # Modelo cinético
    def model(t, C, kd, K_W, Keq):
        CA, CB, CE, CW = C
        denom = (1 + K_W*CW)
        ra = kd * ((CA * CB) - (CE * CW)/Keq) / denom
        return np.array([-ra, -ra, ra, ra])

    # Função objetivo
    def objective(params):
        kd, K_W = params
        sol = solve_ivp(model, [0, max(t_exp)], C0, args=(kd, K_W, Keq), t_eval=t_exp)
        CE_model = sol.y[2]
        return np.mean((CE_model - CE_exp) ** 2)

    # Otimização
    bounds = [(1e-6, 10), (1e-6, 10)]
    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')
    kd, K_W = result.x

    print(f"Parâmetros ajustados: kd={kd:.6f}, K_W={K_W:.4f}")

    # Simulação final
    t_sim = np.linspace(0, max(t_exp), 300)
    sol = solve_ivp(model, [0, max(t_exp)], C0, args=(kd, K_W, Keq), t_eval=t_sim)
    Xa_sim = (CA0 - sol.y[0]) / CA0

    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, sol.y[2]))

    plt.figure(figsize=(10, 6))
    plt.plot(t_sim, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(t_exp, CE_exp, color='red', label='CE (experimental)', zorder=5)
    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'{label}\nkd = {kd:.6f}, K_W={K_W:.3f}\nKeq = {Keq:.6f}, R² = {r2:.4f}')
    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    return t_sim, sol.y[2], Xa_sim, kd, Keq, K_W, r2



