import numpy as np
import matplotlib.pyplot as plt

from scipy.integrate import solve_ivp
from scipy.optimize import minimize
from sklearn.metrics import r2_score


# ============================================================
# MODELO COM K_W FIXO
# ============================================================

def ajustar_modelo_Kw_fixo(
    dados,
    CA0,
    CB0,
    Kw,
    guess=(0.001, 1.0)
):

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    CE_exp = Xa_exp * CA0

    C0 = [
        CA0,
        CB0,
        0.0,
        0.0
    ]

    # ========================================================
    # MODELO CINÉTICO
    # ========================================================

    def model(t, C, kd, Keq):

        CA, CB, CE, CW = C

        denominador = (
            1.0 + Kw * CW
        ) ** 2

        ra = (
            kd
            *
            (
                (CA * CB)
                -
                (CE * CW) / Keq
            )
            /
            denominador
        )

        return np.array([
            -ra,
            -ra,
            ra,
            ra
        ])

    # ========================================================
    # FUNÇÃO OBJETIVO
    # ========================================================

    def objective(params):

        kd, Keq = params

        if kd <= 0 or Keq <= 0:
            return 1e10

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, Keq),
            t_eval=t_exp,
            method='LSODA'
        )

        if not sol.success:
            return 1e10

        CE_model = sol.y[2]

        return np.sqrt(
            np.mean(
                (
                    CE_model
                    -
                    CE_exp
                ) ** 2
            )
        )

    # ========================================================
    # LIMITES
    # ========================================================

    bounds = [
        (1e-8, 10),      # kd
        (1e-6, 100)      # Keq
    ]

    # ========================================================
    # OTIMIZAÇÃO
    # ========================================================

    result = minimize(
        objective,
        guess,
        bounds=bounds,
        method='L-BFGS-B'
    )

    kd, Keq = result.x

    # ========================================================
    # SIMULAÇÃO FINAL NOS PONTOS EXPERIMENTAIS
    # ========================================================

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, Keq),
        t_eval=t_exp,
        method='LSODA'
    )

    CE_model = sol.y[2]

    # ========================================================
    # MÉTRICAS
    # ========================================================

    residuals = (
        CE_model
        -
        CE_exp
    )

    RMSE = np.sqrt(
        np.mean(
            residuals ** 2
        )
    )

    SSE = np.sum(
        residuals ** 2
    )

    R2 = r2_score(
        CE_exp,
        CE_model
    )

    return {
        'Kw': Kw,
        'kd': kd,
        'Keq': Keq,
        'RMSE': RMSE,
        'R2': R2,
        'SSE': SSE,
        'CE_model': CE_model
    }


# ============================================================
# ANÁLISE COMPLETA DE UM EXPERIMENTO
# ============================================================

def analisar_experimento(
    dados,
    CA0,
    CB0,
    nome,
    Kw_values
):

    print("\n")
    print("############################################################")
    print(nome)
    print("############################################################")

    # ========================================================
    # MODELO KW = 0
    # ========================================================

    resultado_zero = ajustar_modelo_Kw_fixo(
        dados=dados,
        CA0=CA0,
        CB0=CB0,
        Kw=0.0,
        guess=(0.001, 1.0)
    )

    print("\n---------------- K_W = 0 ----------------")

    print(
        f"kd   = "
        f"{resultado_zero['kd']:.10f}"
    )

    print(
        f"Keq  = "
        f"{resultado_zero['Keq']:.10f}"
    )

    print(
        f"RMSE = "
        f"{resultado_zero['RMSE']:.8e}"
    )

    print(
        f"R²   = "
        f"{resultado_zero['R2']:.6f}"
    )

    # ========================================================
    # TESTE DE DIFERENTES KW
    # ========================================================

    resultados = []

    guess_atual = (
        resultado_zero['kd'],
        resultado_zero['Keq']
    )

    for Kw in Kw_values:

        resultado = ajustar_modelo_Kw_fixo(
            dados=dados,
            CA0=CA0,
            CB0=CB0,
            Kw=Kw,
            guess=guess_atual
        )

        resultados.append(resultado)

        # Atualiza o chute para facilitar a convergência
        guess_atual = (
            resultado['kd'],
            resultado['Keq']
        )

    # ========================================================
    # MELHOR RMSE
    # ========================================================

    melhor_RMSE = min(
        resultados,
        key=lambda x: x['RMSE']
    )

    # ========================================================
    # MELHOR R²
    # ========================================================

    melhor_R2 = max(
        resultados,
        key=lambda x: x['R2']
    )

    # ========================================================
    # RESULTADOS
    # ========================================================

    print("\n")
    print("------------------------------------------------------------")
    print("RESULTADOS PARA DIFERENTES K_W")
    print("------------------------------------------------------------")

    print(
        f"{'K_W':>10}"
        f"{'kd':>15}"
        f"{'Keq':>15}"
        f"{'RMSE':>18}"
        f"{'R²':>15}"
    )

    print("-" * 75)

    for r in resultados:

        print(
            f"{r['Kw']:10.4f}"
            f"{r['kd']:15.8f}"
            f"{r['Keq']:15.8f}"
            f"{r['RMSE']:18.8e}"
            f"{r['R2']:15.6f}"
        )

    # ========================================================
    # MELHOR RESULTADO
    # ========================================================

    print("\n")
    print("============================================================")
    print("MELHOR RESULTADO - MENOR RMSE")
    print("============================================================")

    print(
        f"K_W  = "
        f"{melhor_RMSE['Kw']:.6f}"
    )

    print(
        f"kd   = "
        f"{melhor_RMSE['kd']:.10f}"
    )

    print(
        f"Keq  = "
        f"{melhor_RMSE['Keq']:.10f}"
    )

    print(
        f"RMSE = "
        f"{melhor_RMSE['RMSE']:.8e}"
    )

    print(
        f"R²   = "
        f"{melhor_RMSE['R2']:.6f}"
    )

    # ========================================================
    # MELHOR R²
    # ========================================================

    print("\n")
    print("============================================================")
    print("MELHOR RESULTADO - MAIOR R²")
    print("============================================================")

    print(
        f"K_W  = "
        f"{melhor_R2['Kw']:.6f}"
    )

    print(
        f"kd   = "
        f"{melhor_R2['kd']:.10f}"
    )

    print(
        f"Keq  = "
        f"{melhor_R2['Keq']:.10f}"
    )

    print(
        f"RMSE = "
        f"{melhor_R2['RMSE']:.8e}"
    )

    print(
        f"R²   = "
        f"{melhor_R2['R2']:.6f}"
    )

    # ========================================================
    # COMPARAÇÃO COM KW = 0
    # ========================================================

    variacao_RMSE = (
        (
            melhor_RMSE['RMSE']
            -
            resultado_zero['RMSE']
        )
        /
        resultado_zero['RMSE']
        *
        100
    )

    variacao_R2 = (
        melhor_RMSE['R2']
        -
        resultado_zero['R2']
    )

    print("\n")
    print("============================================================")
    print("COMPARAÇÃO COM K_W = 0")
    print("============================================================")

    print(
        f"RMSE (K_W = 0) = "
        f"{resultado_zero['RMSE']:.8e}"
    )

    print(
        f"RMSE (melhor K_W) = "
        f"{melhor_RMSE['RMSE']:.8e}"
    )

    print(
        f"Variação do RMSE = "
        f"{variacao_RMSE:.4f}%"
    )

    print(
        f"R² (K_W = 0) = "
        f"{resultado_zero['R2']:.6f}"
    )

    print(
        f"R² (melhor K_W) = "
        f"{melhor_RMSE['R2']:.6f}"
    )

    print(
        f"ΔR² = "
        f"{variacao_R2:.6f}"
    )

    # ========================================================
    # GRÁFICO RMSE x KW
    # ========================================================

    Kw_plot = np.array([
        r['Kw']
        for r in resultados
    ])

    RMSE_plot = np.array([
        r['RMSE']
        for r in resultados
    ])

    R2_plot = np.array([
        r['R2']
        for r in resultados
    ])

    plt.figure(figsize=(8, 5))

    plt.plot(
        Kw_plot,
        RMSE_plot,
        marker='o',
        linewidth=2
    )

    plt.xlabel(r'$K_W$')
    plt.ylabel('RMSE (mol L$^{-1}$)')

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    # ========================================================
    # GRÁFICO R² x KW
    # ========================================================

    plt.figure(figsize=(8, 5))

    plt.plot(
        Kw_plot,
        R2_plot,
        marker='o',
        linewidth=2
    )

    plt.xlabel(r'$K_W$')
    plt.ylabel(r'$R^2$')

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    # ========================================================
    # CURVAS DOS MODELOS
    # ========================================================

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]
    CE_exp = Xa_exp * CA0

    C0 = [
        CA0,
        CB0,
        0.0,
        0.0
    ]

    # Modelo genérico para gerar curvas contínuas
    def model_plot(
        t,
        C,
        kd,
        Keq,
        Kw
    ):

        CA, CB, CE, CW = C

        denom = (
            1 + Kw * CW
        ) ** 2

        ra = (
            kd
            *
            (
                (CA * CB)
                -
                (CE * CW) / Keq
            )
            /
            denom
        )

        return [
            -ra,
            -ra,
            ra,
            ra
        ]

    t_sim = np.linspace(
        0,
        max(t_exp),
        500
    )

    plt.figure(figsize=(9, 5.5))

    # K_W = 0
    sol_zero = solve_ivp(
        model_plot,
        [0, max(t_exp)],
        C0,
        args=(
            resultado_zero['kd'],
            resultado_zero['Keq'],
            0.0
        ),
        t_eval=t_sim,
        method='LSODA'
    )

    plt.plot(
        t_sim,
        sol_zero.y[2],
        linewidth=3,
        label='$K_W = 0$'
    )

    # Melhor K_W
    sol_best = solve_ivp(
        model_plot,
        [0, max(t_exp)],
        C0,
        args=(
            melhor_RMSE['kd'],
            melhor_RMSE['Keq'],
            melhor_RMSE['Kw']
        ),
        t_eval=t_sim,
        method='LSODA'
    )

    plt.plot(
        t_sim,
        sol_best.y[2],
        linewidth=2,
        linestyle='--',
        label=(
            f"Best $K_W$ = "
            f"{melhor_RMSE['Kw']:g}"
        )
    )

    plt.scatter(
        t_exp,
        CE_exp,
        color='red',
        s=45,
        zorder=10,
        label='Experimental'
    )

    plt.xlabel('Time (min)')
    plt.ylabel(r'$C_E$ (mol L$^{-1}$)')

    plt.legend(
        frameon=False
    )

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    # ========================================================
    # RETORNO
    # ========================================================

    return {
        'Kw_zero': resultado_zero,
        'resultados': resultados,
        'melhor_RMSE': melhor_RMSE,
        'melhor_R2': melhor_R2
    }


