import numpy as np
import matplotlib.pyplot as plt

# ======================
# FUNÇÃO DE PLOT
# ======================
def plot_temp(ref, calc, T, cor):
    plt.plot(ref[:,0], ref[:,1], 'o--', color=cor, label=f'Ref {T} K')
    plt.plot(calc[:,0], calc[:,1], '-', color=cor, linewidth=2, label=f'Calc {T} K')

# ======================
# CORES FIXAS
# ======================
cores = {
    333: 'blue',
    343: 'green',
    353: 'red',
    363: 'purple',
    373: 'orange'
}

# ======================
# PLOT PRINCIPAL
# ======================
plt.figure(figsize=(10,6))

plot_temp(dados_333_ref, dados_333_calc, 333, cores[333])
plot_temp(dados_343_ref, dados_343_calc, 343, cores[343])
plot_temp(dados_353_ref, dados_353_calc, 353, cores[353])
plot_temp(dados_363_ref, dados_363_calc, 363, cores[363])
plot_temp(dados_373_ref, dados_373_calc, 373, cores[373])

plt.xlabel('Tempo (h)')
plt.ylabel('Concentração (mol/L)')
#plt.title('Comparação Modelo vs Dados Experimentais')
plt.legend()
plt.grid()

plt.show()

# ======================
# ANÁLISE DE ERRO
# ======================
def erro_medio(ref, calc):
    # interpolação simples para alinhar pontos
    calc_interp = np.interp(ref[:,0], calc[:,0], calc[:,1])
    erro = np.abs(ref[:,1] - calc_interp)
    return np.mean(erro)

erros = {
    333: erro_medio(dados_333_ref, dados_333_calc),
    343: erro_medio(dados_343_ref, dados_343_calc),
    353: erro_medio(dados_353_ref, dados_353_calc),
    363: erro_medio(dados_363_ref, dados_363_calc),
    373: erro_medio(dados_373_ref, dados_373_calc),
}

# ======================
# PLOT DE ERRO
# ======================
plt.figure(figsize=(8,5))

temps = list(erros.keys())
valores = list(erros.values())

plt.plot(temps, valores, 'o-', linewidth=2)
plt.xlabel('Temperatura (K)')
plt.ylabel('Erro médio absoluto (mol/L)')
plt.title('Erro médio do modelo por temperatura')
plt.grid()

plt.show()

# ======================
# PRINT DOS ERROS
# ======================
for T, e in erros.items():
    print(f"T = {T} K -> Erro médio = {e:.4f}")

def desvio_padrao_erro(ref, calc):
    calc_interp = np.interp(ref[:,0], calc[:,0], calc[:,1])
    erro = ref[:,1] - calc_interp
    return np.std(erro)

desvios = {
    333: desvio_padrao_erro(dados_333_ref, dados_333_calc),
    343: desvio_padrao_erro(dados_343_ref, dados_343_calc),
    353: desvio_padrao_erro(dados_353_ref, dados_353_calc),
    363: desvio_padrao_erro(dados_363_ref, dados_363_calc),
    373: desvio_padrao_erro(dados_373_ref, dados_373_calc),
}

