def erro_percentual_medio(ref, calc):
    calc_interp = np.interp(ref[:,0], calc[:,0], calc[:,1])

    # evita divisão por zero
    mask = ref[:,1] != 0

    erro_perc = np.abs((ref[:,1][mask] - calc_interp[mask]) / ref[:,1][mask]) * 100
    return np.mean(erro_perc)

