def pseudo_estado_estacionario_ER(dados, label, CA0, CB0, Ccat=0.26, guess=(0.001, 1.0)):
    """
    Ajusta kd + K_W usando o modelo de Langmuir-Hinshelwood simplificado
    (K_A, K_B, K_E desprezados).

    Modelo cinético:
    ra = (kd * (CA*CB - CE*CW/Keq)) / (1 + K_W*CW)
    """

    # Extrai dados
    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]
    CE_exp = Xa_exp * CA0

    C0 = [CA0, CB0, 0.0, 0.0]

    # Keq do equilíbrio experimental
    CE_eq = CE_exp[-1]
    CW_eq = CE_eq
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = 4
    print(f"Keq (do equilíbrio) = {Keq:.6f}")

    # Modelo cinético
    def model(t, C, kd, K_W, Keq):
        CA, CB, CE, CW = C
        denom = (1 + K_W*CW)
        ra = kd * ((CA * CB) - (CE * CW)/Keq) / denom
        return np.array([-ra, -ra, ra, ra])

    # Função objetivo
    def objective(params):
        kd, K_W = params
        sol = solve_ivp(model, [0, max(t_exp)], C0, args=(kd, K_W, Keq), t_eval=t_exp)
        CE_model = sol.y[2]
        return np.sqrt(np.mean((CE_model - CE_exp) ** 2))    # RSME

    # Otimização
    bounds = [(1e-6, 10), (1e-6, 10)]
    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')
    kd, K_W = result.x

    print(f"Parâmetros ajustados: kd={kd:.6f}, K_W={K_W:.4f}")

    # Simulação final
    t_sim = np.linspace(0, max(t_exp), 300)
    sol = solve_ivp(model, [0, max(t_exp)], C0, args=(kd, K_W, Keq), t_eval=t_sim)
    Xa_sim = (CA0 - sol.y[0]) / CA0
    erro = (CA0- sol.y[0]) - sol.y[2]
    print(f'O erro é {erro}')
    erro2 = (CB0 - sol.y[1]) - sol.y[2]
    print(f'O erro 2 é {erro2}')
    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, sol.y[2]))
    CA, CB, CE, CW = sol.y[:, -1]
    r_final = kd * ((CA*CB) - (CE*CW)/Keq) / (1 + K_W*CW)
    print(f'O r final é de {r_final}')
    plt.figure(figsize=(10, 6))
    plt.plot(t_sim, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(t_exp, CE_exp, color='red', label='CE (experimental)', zorder=5)
    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'{label}\nkd = {kd:.6f}, K_W={K_W:.3f}\nKeq = {Keq:.6f}, R² = {r2:.4f}')
    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    return t_sim, sol.y[2], Xa_sim, kd, Keq, K_W, r2

def pseudo_estado_estacionario_ER_comKeq(dados, label, CA0, CB0, Ccat=0.26, guess=(0.001, 1.0, 4.0)):
    """
    Ajusta kd, K_W e Keq usando modelo simplificado de Langmuir-Hinshelwood
    """

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]
    CE_exp = Xa_exp * CA0

    C0 = [CA0, CB0, 0.0, 0.0]

    # Modelo cinético
    def model(t, C, kd, K_W, Keq):
        CA, CB, CE, CW = C
        denom = (1 + K_W * CW)
        ra = kd * ((CA * CB) - (CE * CW) / Keq) / denom
        return np.array([-ra, -ra, ra, ra])

    # Função objetivo
    def objective(params):
        kd, K_W, Keq = params

        # Evita valores fisicamente inválidos
        if Keq <= 0:
            return 1e10

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, K_W, Keq),
            t_eval=t_exp
        )

        CE_model = sol.y[2]
        return np.sqrt(np.mean((CE_model - CE_exp) ** 2))  # RMSE

    # Bounds (importante limitar Keq!)
    bounds = [
        (1e-6, 10),   # kd
        (1e-6, 10),   # K_W
        (1e-3, 100)   # Keq (ajuste com cuidado)
    ]

    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')
    kd, K_W, Keq = result.x

    print(f"Parâmetros ajustados: kd={kd:.6f}, K_W={K_W:.4f}, Keq={Keq:.4f}")

    # Simulação final
    t_sim = np.linspace(0, max(t_exp), 300)
    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, K_W, Keq),
        t_eval=t_sim
    )

    Xa_sim = (CA0 - sol.y[0]) / CA0

    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, sol.y[2]))

    CA, CB, CE, CW = sol.y[:, -1]
    r_final = kd * ((CA * CB) - (CE * CW) / Keq) / (1 + K_W * CW)

    print(f"R² = {r2:.4f}")
    print(f"r final = {r_final}")

    plt.figure(figsize=(10, 6))
    plt.plot(t_sim, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(t_exp, CE_exp, color='red', label='CE (experimental)', zorder=5)
    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'{label}\nkd={kd:.6f}, K_W={K_W:.3f}, Keq={Keq:.3f}, R²={r2:.4f}')
    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    return t_sim, sol.y[2], Xa_sim, kd, Keq, K_W, r2

import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import minimize
from sklearn.metrics import r2_score
import matplotlib.pyplot as plt

def ajuste_com_Keq_robusto(dados, label, CA0, CB0, guess=(1e-3, 1.0, 10.0)):

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]
    CE_exp = Xa_exp * CA0

    C0 = [CA0, CB0, 0.0, 0.0]

    # =========================
    # Modelo cinético
    # =========================
    def model(t, C, kd, K_W, Keq):
        CA, CB, CE, CW = C
        denom = (1 + K_W * CW)
        ra = kd * ((CA * CB) - (CE * CW) / Keq) / denom
        return [-ra, -ra, ra, ra]

    # =========================
    # Função objetivo robusta
    # =========================
    def objective(log_params):
        # trabalha em log (muito mais estável)
        kd, K_W, Keq = np.exp(log_params)

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, K_W, Keq),
            t_eval=t_exp,
            method='LSODA'
        )

        if not sol.success:
            return 1e10

        CE_model = sol.y[2]

        # =========================
        # Erro principal (RMSE)
        # =========================
        rmse = np.sqrt(np.mean((CE_model - CE_exp) ** 2))

        # =========================
        # Penalização de equilíbrio
        # =========================
        CAf, CBf, CEf, CWf = sol.y[:, -1]

        eq_residual = (CAf * CBf) - (CEf * CWf) / Keq

        penalty_eq = abs(eq_residual)

        # =========================
        # Peso maior no final
        # =========================
        peso_final = 5.0
        erro_final = peso_final * abs(CE_model[-1] - CE_exp[-1])

        return rmse + erro_final + 10 * penalty_eq

    # =========================
    # Chute inicial em log
    # =========================
    log_guess = np.log(guess)

    result = minimize(
        objective,
        log_guess,
        method='L-BFGS-B'
    )

    kd, K_W, Keq = np.exp(result.x)

    print(f"kd = {kd:.6f}")
    print(f"K_W = {K_W:.4f}")
    print(f"Keq = {Keq:.4f}")

    # =========================
    # Simulação final
    # =========================
    t_sim = np.linspace(0, max(t_exp), 300)

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, K_W, Keq),
        t_eval=t_sim,
        method='LSODA'
    )

    CE_sim = sol.y[2]

    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, CE_sim))

    print(f"R² = {r2:.4f}")

    # =========================
    # Checagem de equilíbrio
    # =========================
    CAf, CBf, CEf, CWf = sol.y[:, -1]
    check_eq = (CAf * CBf) - (CEf * CWf) / Keq

    print(f"Resíduo de equilíbrio = {check_eq:.6e}")

    # =========================
    # Plot
    # =========================
    plt.figure(figsize=(10,6))
    plt.plot(t_sim, CE_sim, label='Modelo')
    plt.scatter(t_exp, CE_exp, color='red', label='Experimental')
    plt.legend()
    plt.grid()
    plt.title(f"{label} | Keq={Keq:.2f} | R²={r2:.4f}")
    plt.show()

    return kd, K_W, Keq, r2

