import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import minimize
from sklearn.metrics import r2_score
import matplotlib.pyplot as plt

def pseudo_estado_estacionario_ER_sem_Kw(dados, label, CA0, CB0, Ccat=0.26, guess=(0.001, 4.0)):
    """
    Ajusta kd e Keq com K_W = 0 (sem adsorção de água)
    """

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]
    CE_exp = Xa_exp * CA0

    C0 = [CA0, CB0, 0.0, 0.0]

    # =========================
    # Modelo cinético (Kw = 0)
    # =========================
    def model(t, C, kd, Keq):
        CA, CB, CE, CW = C
        ra = kd * ((CA * CB) - (CE * CW) / Keq)
        return np.array([-ra, -ra, ra, ra])

    # =========================
    # Função objetivo
    # =========================
    def objective(params):
        kd, Keq = params

        if Keq <= 0 or kd <= 0:
            return 1e10

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, Keq),
            t_eval=t_exp
        )

        if not sol.success:
            return 1e10

        CE_model = sol.y[2]

        return np.sqrt(np.mean((CE_model - CE_exp) ** 2))  # RMSE

    # =========================
    # Bounds
    # =========================
    bounds = [
        (1e-6, 10),   # kd
        (1e-3, 100)   # Keq
    ]

    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')
    kd, Keq = result.x

    print(f"Parâmetros ajustados: kd={kd:.6f}, Keq={Keq:.4f}")

    # =========================
    # Simulação final
    # =========================
    t_sim = np.linspace(0, max(t_exp), 300)

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, Keq),
        t_eval=t_sim
    )

    Xa_sim = (CA0 - sol.y[0]) / CA0

    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, sol.y[2]))

    # =========================
    # Checagem física (equilíbrio)
    # =========================
    CA, CB, CE, CW = sol.y[:, -1]
    r_final = kd * ((CA * CB) - (CE * CW) / Keq)

    print(f"R² = {r2:.4f}")
    print(f"r final = {r_final:.6e}")

    # =========================
    # Plot
    # =========================
    plt.figure(figsize=(10, 6))
    plt.plot(t_sim, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(t_exp, CE_exp, color='red', label='CE (experimental)', zorder=5)
    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'{label}\nkd={kd:.6f}, Keq={Keq:.3f}, R²={r2:.4f}')
    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    return t_sim, sol.y[2], Xa_sim, kd, Keq, r2

