import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import minimize
from sklearn.metrics import r2_score
import matplotlib.pyplot as plt


# ============================================================
# MODELO LHHW - AJUSTE COM K_W = 0
# ============================================================

def pseudo_estado_estacionario_ER_sem_Kw(
    dados,
    label,
    CA0,
    CB0,
    Ccat=0.26,
    guess=(0.001, 4.0)
):

    """
    Ajusta kd e Keq considerando K_W = 0.
    """

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    # Concentração experimental de éster
    CE_exp = Xa_exp * CA0

    # Condições iniciais
    C0 = [CA0, CB0, 0.0, 0.0]

    # ========================================================
    # MODELO CINÉTICO COM K_W = 0
    # ========================================================

    def model(t, C, kd, Keq):

        CA, CB, CE, CW = C

        ra = kd * (
            (CA * CB)
            -
            (CE * CW) / Keq
        )

        return np.array([
            -ra,
            -ra,
            ra,
            ra
        ])

    # ========================================================
    # FUNÇÃO OBJETIVO
    # ========================================================

    def objective(params):

        kd, Keq = params

        if Keq <= 0 or kd <= 0:
            return 1e10

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, Keq),
            t_eval=t_exp
        )

        if not sol.success:
            return 1e10

        CE_model = sol.y[2]

        RMSE = np.sqrt(
            np.mean(
                (CE_model - CE_exp) ** 2
            )
        )

        return RMSE

    # ========================================================
    # LIMITES DOS PARÂMETROS
    # ========================================================

    bounds = [
        (1e-6, 10),     # kd
        (1e-3, 100)     # Keq
    ]

    # ========================================================
    # OTIMIZAÇÃO
    # ========================================================

    result = minimize(
        objective,
        guess,
        bounds=bounds,
        method='L-BFGS-B'
    )

    kd, Keq = result.x

    print("\n==============================================")
    print("AJUSTE DO MODELO COM K_W = 0")
    print("==============================================")

    print(f"Parâmetros ajustados:")
    print(f"kd   = {kd:.10f}")
    print(f"Keq  = {Keq:.10f}")

    # ========================================================
    # SIMULAÇÃO FINAL
    # ========================================================

    t_sim = np.linspace(
        0,
        max(t_exp),
        300
    )

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, Keq),
        t_eval=t_sim
    )

    CE_sim = sol.y[2]

    Xa_sim = (
        CA0 - sol.y[0]
    ) / CA0

    # ========================================================
    # R²
    # ========================================================

    CE_model_exp = np.interp(
        t_exp,
        t_sim,
        CE_sim
    )

    r2 = r2_score(
        CE_exp,
        CE_model_exp
    )

    # ========================================================
    # CHECAGEM FÍSICA
    # ========================================================

    CA, CB, CE, CW = sol.y[:, -1]

    r_final = kd * (
        (CA * CB)
        -
        (CE * CW) / Keq
    )

    print(f"\nR² = {r2:.6f}")
    print(f"r final = {r_final:.6e}")

    # ========================================================
    # GRÁFICO DO AJUSTE
    # ========================================================

    plt.figure(figsize=(10, 6))

    plt.plot(
        t_sim,
        CE_sim,
        label='CE (simulated)',
        linewidth=2
    )

    plt.scatter(
        t_exp,
        CE_exp,
        color='red',
        label='CE (experimental)',
        zorder=5
    )

    plt.xlabel('Time (min)')
    plt.ylabel('Concentration (mol L$^{-1}$)')

    plt.title(
        f'{label}\n'
        f'$k_d$={kd:.6f}, '
        f'$K_{{eq}}$={Keq:.3f}, '
        f'$R^2$={r2:.4f}'
    )

    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    return (
        t_sim,
        CE_sim,
        Xa_sim,
        kd,
        Keq,
        r2
    )


# ============================================================
# ANÁLISE DE SENSIBILIDADE PARAMÉTRICA DE K_W
# ============================================================

def analise_sensibilidade_Kw(
    dados,
    CA0,
    CB0,
    kd,
    Keq,
    Ccat=0.26,
    Kw_values=None
):

    """
    Avalia a sensibilidade do modelo ao parâmetro K_W.

    kd e Keq permanecem fixos nos valores obtidos
    pelo ajuste com K_W = 0.
    """

    # ========================================================
    # VALORES DE K_W TESTADOS
    # ========================================================

    if Kw_values is None:

        Kw_values = np.array([
            0.000,
            0.001,
            0.005,
            0.010,
            0.025,
            0.050,
            0.100,
            0.250,
            0.500,
            1.000,
            2.000,
            5.000,
            10.000
        ])

    # ========================================================
    # DADOS EXPERIMENTAIS
    # ========================================================

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    CE_exp = Xa_exp * CA0

    # Condições iniciais
    C0 = [
        CA0,
        CB0,
        0.0,
        0.0
    ]

    # Tempo de simulação
    t_sim = np.linspace(
        0,
        max(t_exp),
        500
    )

    # ========================================================
    # MODELO COMPLETO COM K_W
    # ========================================================

    def model_Kw(
        t,
        C,
        kd,
        Keq,
        Kw
    ):

        CA, CB, CE, CW = C

        denominador = (
            1 + Kw * CW
        ) ** 2

        ra = (
            kd
            *
            (
                (CA * CB)
                -
                (CE * CW) / Keq
            )
            /
            denominador
        )

        return np.array([
            -ra,
            -ra,
            ra,
            ra
        ])

    # ========================================================
    # ARMAZENAMENTO DOS RESULTADOS
    # ========================================================

    resultados = []

    curvas = {}

    # ========================================================
    # GRÁFICO DAS CURVAS
    # ========================================================

    plt.figure(figsize=(10, 6))

    for Kw in Kw_values:

        sol = solve_ivp(
            model_Kw,
            [0, max(t_exp)],
            C0,
            args=(
                kd,
                Keq,
                Kw
            ),
            t_eval=t_sim,
            method='LSODA'
        )

        if not sol.success:

            print(
                f"Falha na simulação para K_W = {Kw}"
            )

            continue

        CE_model = sol.y[2]

        curvas[Kw] = CE_model

        # ----------------------------------------------------
        # Valores nos pontos experimentais
        # ----------------------------------------------------

        CE_interp = np.interp(
            t_exp,
            t_sim,
            CE_model
        )

        # ----------------------------------------------------
        # RMSE
        # ----------------------------------------------------

        rmse = np.sqrt(
            np.mean(
                (
                    CE_interp
                    -
                    CE_exp
                ) ** 2
            )
        )

        # ----------------------------------------------------
        # R²
        # ----------------------------------------------------

        r2 = r2_score(
            CE_exp,
            CE_interp
        )

        # ----------------------------------------------------
        # Soma dos quadrados dos resíduos
        # ----------------------------------------------------

        SSE = np.sum(
            (
                CE_interp
                -
                CE_exp
            ) ** 2
        )

        # ----------------------------------------------------
        # Valor final de CE
        # ----------------------------------------------------

        CE_final = CE_model[-1]

        # ----------------------------------------------------
        # Armazenamento
        # ----------------------------------------------------

        resultados.append([
            Kw,
            rmse,
            r2,
            SSE,
            CE_final
        ])

        # ----------------------------------------------------
        # Curva
        # ----------------------------------------------------

        plt.plot(
            t_sim,
            CE_model,
            linewidth=2,
            label=f'$K_W$ = {Kw:g}'
        )

    # ========================================================
    # DADOS EXPERIMENTAIS
    # ========================================================

    plt.scatter(
        t_exp,
        CE_exp,
        color='black',
        s=45,
        zorder=10,
        label='Experimental'
    )

    plt.xlabel('Time (min)')
    plt.ylabel(r'$C_E$ (mol L$^{-1}$)')

    plt.legend(
        fontsize=8,
        frameon=False
    )

    plt.grid(False)

    plt.tight_layout()
    plt.show()

    # ========================================================
    # CONVERTE PARA ARRAY
    # ========================================================

    resultados = np.array(
        resultados
    )

    # ========================================================
    # TABELA NO TERMINAL
    # ========================================================

    print("\n")
    print("==============================================================")
    print("ANÁLISE DE SENSIBILIDADE PARAMÉTRICA DE K_W")
    print("==============================================================")

    print(
        f"{'K_W':>10}"
        f"{'RMSE':>18}"
        f"{'R²':>15}"
        f"{'SSE':>18}"
        f"{'CE final':>18}"
    )

    print("--------------------------------------------------------------")

    for linha in resultados:

        print(
            f"{linha[0]:10.4f}"
            f"{linha[1]:18.8e}"
            f"{linha[2]:15.6f}"
            f"{linha[3]:18.8e}"
            f"{linha[4]:18.8f}"
        )

    # ========================================================
    # IDENTIFICA MELHOR RMSE
    # ========================================================

    indice_melhor = np.argmin(
        resultados[:, 1]
    )

    Kw_melhor = resultados[
        indice_melhor,
        0
    ]

    rmse_melhor = resultados[
        indice_melhor,
        1
    ]

    r2_melhor = resultados[
        indice_melhor,
        2
    ]

    print("\n==============================================================")
    print("MELHOR RESULTADO")
    print("==============================================================")

    print(
        f"K_W com menor RMSE = {Kw_melhor:.6f}"
    )

    print(
        f"RMSE = {rmse_melhor:.8e}"
    )

    print(
        f"R² = {r2_melhor:.6f}"
    )

    # ========================================================
    # GRÁFICO RMSE x K_W
    # ========================================================

    plt.figure(figsize=(8, 5))

    plt.plot(
        resultados[:, 0],
        resultados[:, 1],
        marker='o',
        linewidth=2
    )

    plt.xlabel(r'$K_W$')
    plt.ylabel('RMSE (mol L$^{-1}$)')

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    # ========================================================
    # GRÁFICO R² x K_W
    # ========================================================

    plt.figure(figsize=(8, 5))

    plt.plot(
        resultados[:, 0],
        resultados[:, 2],
        marker='o',
        linewidth=2
    )

    plt.xlabel(r'$K_W$')
    plt.ylabel(r'$R^2$')

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    # ========================================================
    # SENSIBILIDADE RELATIVA EM RELAÇÃO AO CASO K_W = 0
    # ========================================================

    # Localiza o resultado de Kw = 0
    indice_zero = np.argmin(
        np.abs(resultados[:, 0])
    )

    RMSE_zero = resultados[
        indice_zero,
        1
    ]

    R2_zero = resultados[
        indice_zero,
        2
    ]

    CE_zero = resultados[
        indice_zero,
        4
    ]

    # Diferença relativa do RMSE
    variacao_RMSE = (
        (resultados[:, 1] - RMSE_zero)
        /
        RMSE_zero
        *
        100
    )

    # Diferença relativa de CE final
    variacao_CE_final = (
        (resultados[:, 4] - CE_zero)
        /
        CE_zero
        *
        100
    )

    # ========================================================
    # GRÁFICO DA VARIAÇÃO RELATIVA
    # ========================================================

    plt.figure(figsize=(8, 5))

    plt.plot(
        resultados[:, 0],
        variacao_CE_final,
        marker='o',
        linewidth=2
    )

    plt.axhline(
        0,
        linestyle='--',
        linewidth=1
    )

    plt.xlabel(r'$K_W$')
    plt.ylabel(
        'Variation in final $C_E$ (%)'
    )

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    # ========================================================
    # RESULTADO FINAL
    # ========================================================

    print("\n==============================================================")
    print("COMPARAÇÃO COM K_W = 0")
    print("==============================================================")

    print(
        f"RMSE para K_W = 0: "
        f"{RMSE_zero:.8e}"
    )

    print(
        f"R² para K_W = 0: "
        f"{R2_zero:.6f}"
    )

    print(
        f"CE final para K_W = 0: "
        f"{CE_zero:.8f} mol L^-1"
    )

    print("\nVariação relativa do RMSE:")

    for i in range(len(resultados)):

        print(
            f"K_W = {resultados[i,0]:.4f} "
            f"→ "
            f"{variacao_RMSE[i]:.4f}%"
        )

    print("\nVariação relativa de CE final:")

    for i in range(len(resultados)):

        print(
            f"K_W = {resultados[i,0]:.4f} "
            f"→ "
            f"{variacao_CE_final[i]:.4f}%"
        )

    return (
        resultados,
        curvas,
        variacao_RMSE,
        variacao_CE_final
    )


