import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import minimize, least_squares
from scipy.stats import t as t_student
from sklearn.metrics import r2_score
import matplotlib.pyplot as plt


# ============================================================
# MODELO LHHW - AJUSTE COM K_W = 0
# ============================================================

def pseudo_estado_estacionario_ER_sem_Kw(
    dados,
    label,
    CA0,
    CB0,
    Ccat=0.26,
    guess=(0.001, 4.0)
):

    """
    Ajusta kd e Keq considerando K_W = 0.
    """

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    CE_exp = Xa_exp * CA0

    C0 = [CA0, CB0, 0.0, 0.0]

    # ========================================================
    # MODELO CINÉTICO COM K_W = 0
    # ========================================================

    def model(t, C, kd, Keq):

        CA, CB, CE, CW = C

        ra = kd * (
            (CA * CB)
            -
            (CE * CW) / Keq
        )

        return np.array([
            -ra,
            -ra,
            ra,
            ra
        ])

    # ========================================================
    # FUNÇÃO OBJETIVO
    # ========================================================

    def objective(params):

        kd, Keq = params

        if Keq <= 0 or kd <= 0:
            return 1e10

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(kd, Keq),
            t_eval=t_exp
        )

        if not sol.success:
            return 1e10

        CE_model = sol.y[2]

        RMSE = np.sqrt(
            np.mean(
                (CE_model - CE_exp) ** 2
            )
        )

        return RMSE

    # ========================================================
    # LIMITES
    # ========================================================

    bounds = [
        (1e-6, 10),
        (1e-3, 100)
    ]

    # ========================================================
    # OTIMIZAÇÃO
    # ========================================================

    result = minimize(
        objective,
        guess,
        bounds=bounds,
        method='L-BFGS-B'
    )

    kd, Keq = result.x

    print("\n==============================================")
    print("AJUSTE DO MODELO COM K_W = 0")
    print("==============================================")

    print(f"kd  = {kd:.10f}")
    print(f"Keq = {Keq:.10f}")

    # ========================================================
    # SIMULAÇÃO FINAL
    # ========================================================

    t_sim = np.linspace(
        0,
        max(t_exp),
        300
    )

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(kd, Keq),
        t_eval=t_sim
    )

    CE_sim = sol.y[2]

    Xa_sim = (
        CA0 - sol.y[0]
    ) / CA0

    # ========================================================
    # R²
    # ========================================================

    CE_model_exp = np.interp(
        t_exp,
        t_sim,
        CE_sim
    )

    r2 = r2_score(
        CE_exp,
        CE_model_exp
    )

    # ========================================================
    # RMSE
    # ========================================================

    RMSE = np.sqrt(
        np.mean(
            (CE_model_exp - CE_exp) ** 2
        )
    )

    # ========================================================
    # CHECAGEM FÍSICA
    # ========================================================

    CA, CB, CE, CW = sol.y[:, -1]

    r_final = kd * (
        (CA * CB)
        -
        (CE * CW) / Keq
    )

    print(f"RMSE = {RMSE:.8e}")
    print(f"R²   = {r2:.6f}")
    print(f"r final = {r_final:.6e}")

    # ========================================================
    # GRÁFICO
    # ========================================================

    plt.figure(figsize=(10, 6))

    plt.plot(
        t_sim,
        CE_sim,
        label='CE (simulated)',
        linewidth=2
    )

    plt.scatter(
        t_exp,
        CE_exp,
        color='red',
        label='CE (experimental)',
        zorder=5
    )

    plt.xlabel('Time (min)')
    plt.ylabel('Concentration (mol L$^{-1}$)')

    plt.title(
        f'{label}\n'
        f'$k_d$={kd:.6f}, '
        f'$K_{{eq}}$={Keq:.3f}, '
        f'$R^2$={r2:.4f}'
    )

    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    return (
        t_sim,
        CE_sim,
        Xa_sim,
        kd,
        Keq,
        r2
    )


# ============================================================
# AJUSTE DO MODELO COMPLETO
# kd + Keq + K_W
# ============================================================

def pseudo_estado_estacionario_ER_completo(
    dados,
    label,
    CA0,
    CB0,
    Ccat=0.26,
    guess=(0.001, 4.0, 0.01)
):

    """
    Ajusta simultaneamente:

        kd
        Keq
        K_W

    e calcula o intervalo de confiança de 95% usando
    a distribuição t de Student.
    """

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    CE_exp = Xa_exp * CA0

    C0 = [
        CA0,
        CB0,
        0.0,
        0.0
    ]

    # ========================================================
    # MODELO LHHW COMPLETO
    # ========================================================

    def model(t, C, kd, Keq, Kw):

        CA, CB, CE, CW = C

        denominador = (
            1.0 + Kw * CW
        ) ** 2

        ra = (
            kd
            *
            (
                (CA * CB)
                -
                (CE * CW) / Keq
            )
            /
            denominador
        )

        return np.array([
            -ra,
            -ra,
            ra,
            ra
        ])

    # ========================================================
    # RESÍDUOS
    # ========================================================

    def residuals(params):

        kd, Keq, Kw = params

        if kd <= 0 or Keq <= 0 or Kw < 0:

            return np.ones(
                len(CE_exp)
            ) * 1e6

        sol = solve_ivp(
            model,
            [0, max(t_exp)],
            C0,
            args=(
                kd,
                Keq,
                Kw
            ),
            t_eval=t_exp,
            method='LSODA'
        )

        if not sol.success:

            return np.ones(
                len(CE_exp)
            ) * 1e6

        CE_model = sol.y[2]

        return CE_model - CE_exp

    # ========================================================
    # LIMITES
    # ========================================================

    lower_bounds = [
        1e-8,    # kd
        1e-6,    # Keq
        0.0      # Kw
    ]

    upper_bounds = [
        10.0,    # kd
        100.0,   # Keq
        100.0    # Kw
    ]

    # ========================================================
    # AJUSTE POR MÍNIMOS QUADRADOS
    # ========================================================

    result = least_squares(
        residuals,
        x0=guess,
        bounds=(
            lower_bounds,
            upper_bounds
        ),
        method='trf',
        jac='2-point',
        xtol=1e-12,
        ftol=1e-12,
        gtol=1e-12,
        max_nfev=5000
    )

    kd, Keq, Kw = result.x

    residuos = result.fun

    n = len(residuos)

    p = 3

    graus_liberdade = n - p

    SSE = np.sum(
        residuos ** 2
    )

    RMSE = np.sqrt(
        SSE / n
    )

    # ========================================================
    # MATRIZ DE COVARIÂNCIA
    # ========================================================

    J = result.jac

    JTJ = J.T @ J

    try:

        cov = (
            np.linalg.inv(JTJ)
            *
            SSE
            /
            graus_liberdade
        )

        erro_padrao = np.sqrt(
            np.diag(cov)
        )

    except np.linalg.LinAlgError:

        cov = np.full(
            (p, p),
            np.nan
        )

        erro_padrao = np.full(
            p,
            np.nan
        )

    # ========================================================
    # t DE STUDENT
    # ========================================================

    confianca = 0.95

    alpha = 1 - confianca

    t_critico = t_student.ppf(
        1 - alpha / 2,
        graus_liberdade
    )

    # ========================================================
    # INTERVALOS DE CONFIANÇA
    # ========================================================

    IC_kd = (
        kd - t_critico * erro_padrao[0],
        kd + t_critico * erro_padrao[0]
    )

    IC_Keq = (
        Keq - t_critico * erro_padrao[1],
        Keq + t_critico * erro_padrao[1]
    )

    IC_Kw = (
        Kw - t_critico * erro_padrao[2],
        Kw + t_critico * erro_padrao[2]
    )

    # ========================================================
    # IC FISICAMENTE RESTRITO
    # ========================================================

    IC_Kw_fisico = (
        max(0.0, IC_Kw[0]),
        IC_Kw[1]
    )

    # ========================================================
    # SIMULAÇÃO FINAL
    # ========================================================

    t_sim = np.linspace(
        0,
        max(t_exp),
        500
    )

    sol = solve_ivp(
        model,
        [0, max(t_exp)],
        C0,
        args=(
            kd,
            Keq,
            Kw
        ),
        t_eval=t_sim,
        method='LSODA'
    )

    CE_sim = sol.y[2]

    CE_model_exp = np.interp(
        t_exp,
        t_sim,
        CE_sim
    )

    # ========================================================
    # R²
    # ========================================================

    r2 = r2_score(
        CE_exp,
        CE_model_exp
    )

    # ========================================================
    # RESULTADOS
    # ========================================================

    print("\n")
    print("==============================================================")
    print("AJUSTE DO MODELO COMPLETO - kd + Keq + K_W")
    print("==============================================================")

    print(f"kd  = {kd:.10f}")
    print(f"SE(kd) = {erro_padrao[0]:.10f}")

    print(
        f"IC95% kd = "
        f"[{IC_kd[0]:.10f} ; {IC_kd[1]:.10f}]"
    )

    print("\n")

    print(f"Keq = {Keq:.10f}")
    print(f"SE(Keq) = {erro_padrao[1]:.10f}")

    print(
        f"IC95% Keq = "
        f"[{IC_Keq[0]:.10f} ; {IC_Keq[1]:.10f}]"
    )

    print("\n")

    print(f"K_W = {Kw:.10f}")
    print(f"SE(K_W) = {erro_padrao[2]:.10f}")

    print(
        f"IC95% K_W = "
        f"[{IC_Kw[0]:.10f} ; {IC_Kw[1]:.10f}]"
    )

    print(
        f"IC95% K_W físico = "
        f"[{IC_Kw_fisico[0]:.10f} ; "
        f"{IC_Kw_fisico[1]:.10f}]"
    )

    print("\n")

    print(
        f"Graus de liberdade = "
        f"{graus_liberdade}"
    )

    print(
        f"t crítico (95%) = "
        f"{t_critico:.6f}"
    )

    print(
        f"SSE = {SSE:.8e}"
    )

    print(
        f"RMSE = {RMSE:.8e}"
    )

    print(
        f"R² = {r2:.6f}"
    )

    # ========================================================
    # TESTE DE SIGNIFICÂNCIA DE K_W
    # ========================================================

    t_Kw = (
        Kw
        /
        erro_padrao[2]
    )

    p_Kw = (
        2
        *
        (
            1
            -
            t_student.cdf(
                abs(t_Kw),
                graus_liberdade
            )
        )
    )

    print("\n")
    print("==============================================================")
    print("TESTE t DE STUDENT PARA K_W")
    print("==============================================================")

    print(
        f"t calculado = {t_Kw:.6f}"
    )

    print(
        f"p-valor = {p_Kw:.6f}"
    )

    if p_Kw < 0.05:

        print(
            "Resultado: K_W estatisticamente diferente de zero "
            "(p < 0.05)."
        )

    else:

        print(
            "Resultado: não foi possível rejeitar "
            "K_W = 0 ao nível de 5%."
        )

    # ========================================================
    # AVISO SOBRE LIMITE INFERIOR
    # ========================================================

    if IC_Kw[0] < 0:

        print("\nATENÇÃO:")

        print(
            "O limite inferior do IC estatístico é negativo."
        )

        print(
            "Como K_W >= 0 fisicamente, o intervalo "
            "foi adicionalmente apresentado com limite "
            "inferior truncado em zero."
        )

    # ========================================================
    # GRÁFICO
    # ========================================================

    plt.figure(figsize=(10, 6))

    plt.plot(
        t_sim,
        CE_sim,
        linewidth=2,
        label='CE (simulated)'
    )

    plt.scatter(
        t_exp,
        CE_exp,
        color='red',
        s=45,
        zorder=5,
        label='CE (experimental)'
    )

    plt.xlabel('Time (min)')
    plt.ylabel('Concentration (mol L$^{-1}$)')

    plt.title(
        f'{label}\n'
        f'$k_d$={kd:.6f}, '
        f'$K_{{eq}}$={Keq:.3f}, '
        f'$K_W$={Kw:.6f}, '
        f'$R^2$={r2:.4f}'
    )

    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    return {
        'kd': kd,
        'Keq': Keq,
        'Kw': Kw,
        'SE_kd': erro_padrao[0],
        'SE_Keq': erro_padrao[1],
        'SE_Kw': erro_padrao[2],
        'IC_kd': IC_kd,
        'IC_Keq': IC_Keq,
        'IC_Kw': IC_Kw,
        'IC_Kw_fisico': IC_Kw_fisico,
        't_critico': t_critico,
        'graus_liberdade': graus_liberdade,
        't_Kw': t_Kw,
        'p_Kw': p_Kw,
        'SSE': SSE,
        'RMSE': RMSE,
        'R2': r2,
        't_sim': t_sim,
        'CE_sim': CE_sim
    }


# ============================================================
# ANÁLISE DE SENSIBILIDADE PARAMÉTRICA DE K_W
# ============================================================

def analise_sensibilidade_Kw(
    dados,
    CA0,
    CB0,
    kd,
    Keq,
    Ccat=0.26,
    Kw_values=None
):

    """
    Avalia a sensibilidade do modelo ao parâmetro K_W.

    kd e Keq permanecem fixos.
    """

    if Kw_values is None:

        Kw_values = np.array([
            0.000,
            0.001,
            0.005,
            0.010,
            0.025,
            0.050,
            0.100,
            0.250,
            0.500,
            1.000,
            2.000,
            5.000,
            10.000
        ])

    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]

    CE_exp = Xa_exp * CA0

    C0 = [
        CA0,
        CB0,
        0.0,
        0.0
    ]

    t_sim = np.linspace(
        0,
        max(t_exp),
        500
    )

    # ========================================================
    # MODELO
    # ========================================================

    def model_Kw(
        t,
        C,
        kd,
        Keq,
        Kw
    ):

        CA, CB, CE, CW = C

        denominador = (
            1 + Kw * CW
        ) ** 2

        ra = (
            kd
            *
            (
                (CA * CB)
                -
                (CE * CW) / Keq
            )
            /
            denominador
        )

        return np.array([
            -ra,
            -ra,
            ra,
            ra
        ])

    resultados = []

    curvas = {}

    # ========================================================
    # CURVAS
    # ========================================================

    plt.figure(figsize=(10, 6))

    for Kw in Kw_values:

        sol = solve_ivp(
            model_Kw,
            [0, max(t_exp)],
            C0,
            args=(
                kd,
                Keq,
                Kw
            ),
            t_eval=t_sim,
            method='LSODA'
        )

        if not sol.success:
            continue

        CE_model = sol.y[2]

        curvas[Kw] = CE_model

        CE_interp = np.interp(
            t_exp,
            t_sim,
            CE_model
        )

        rmse = np.sqrt(
            np.mean(
                (
                    CE_interp
                    -
                    CE_exp
                ) ** 2
            )
        )

        r2 = r2_score(
            CE_exp,
            CE_interp
        )

        SSE = np.sum(
            (
                CE_interp
                -
                CE_exp
            ) ** 2
        )

        CE_final = CE_model[-1]

        resultados.append([
            Kw,
            rmse,
            r2,
            SSE,
            CE_final
        ])

        plt.plot(
            t_sim,
            CE_model,
            linewidth=2,
            label=f'$K_W$ = {Kw:g}'
        )

    plt.scatter(
        t_exp,
        CE_exp,
        color='black',
        s=45,
        zorder=10,
        label='Experimental'
    )

    plt.xlabel('Time (min)')
    plt.ylabel(r'$C_E$ (mol L$^{-1}$)')

    plt.legend(
        fontsize=8,
        frameon=False
    )

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    resultados = np.array(
        resultados
    )

    # ========================================================
    # TABELA
    # ========================================================

    print("\n")
    print("==============================================================")
    print("ANÁLISE DE SENSIBILIDADE PARAMÉTRICA DE K_W")
    print("==============================================================")

    print(
        f"{'K_W':>10}"
        f"{'RMSE':>18}"
        f"{'R²':>15}"
        f"{'SSE':>18}"
        f"{'CE final':>18}"
    )

    print("--------------------------------------------------------------")

    for linha in resultados:

        print(
            f"{linha[0]:10.4f}"
            f"{linha[1]:18.8e}"
            f"{linha[2]:15.6f}"
            f"{linha[3]:18.8e}"
            f"{linha[4]:18.8f}"
        )

    # ========================================================
    # MELHOR RESULTADO
    # ========================================================

    indice_melhor = np.argmin(
        resultados[:, 1]
    )

    print("\n==============================================================")
    print("MELHOR RESULTADO")
    print("==============================================================")

    print(
        f"K_W = "
        f"{resultados[indice_melhor,0]:.6f}"
    )

    print(
        f"RMSE = "
        f"{resultados[indice_melhor,1]:.8e}"
    )

    print(
        f"R² = "
        f"{resultados[indice_melhor,2]:.6f}"
    )

    # ========================================================
    # RMSE x KW
    # ========================================================

    plt.figure(figsize=(8, 5))

    plt.plot(
        resultados[:, 0],
        resultados[:, 1],
        marker='o',
        linewidth=2
    )

    plt.xlabel(r'$K_W$')
    plt.ylabel('RMSE (mol L$^{-1}$)')

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    # ========================================================
    # R² x KW
    # ========================================================

    plt.figure(figsize=(8, 5))

    plt.plot(
        resultados[:, 0],
        resultados[:, 2],
        marker='o',
        linewidth=2
    )

    plt.xlabel(r'$K_W$')
    plt.ylabel(r'$R^2$')

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    # ========================================================
    # COMPARAÇÃO COM KW = 0
    # ========================================================

    indice_zero = np.argmin(
        np.abs(
            resultados[:, 0]
        )
    )

    RMSE_zero = resultados[
        indice_zero,
        1
    ]

    R2_zero = resultados[
        indice_zero,
        2
    ]

    CE_zero = resultados[
        indice_zero,
        4
    ]

    variacao_RMSE = (
        (
            resultados[:, 1]
            -
            RMSE_zero
        )
        /
        RMSE_zero
        *
        100
    )

    variacao_CE_final = (
        (
            resultados[:, 4]
            -
            CE_zero
        )
        /
        CE_zero
        *
        100
    )

    # ========================================================
    # GRÁFICO DA VARIAÇÃO DE CE
    # ========================================================

    plt.figure(figsize=(8, 5))

    plt.plot(
        resultados[:, 0],
        variacao_CE_final,
        marker='o',
        linewidth=2
    )

    plt.axhline(
        0,
        linestyle='--',
        linewidth=1
    )

    plt.xlabel(r'$K_W$')
    plt.ylabel(
        'Variation in final $C_E$ (%)'
    )

    plt.grid(False)
    plt.tight_layout()
    plt.show()

    # ========================================================
    # RESULTADOS
    # ========================================================

    print("\n==============================================================")
    print("COMPARAÇÃO COM K_W = 0")
    print("==============================================================")

    print(
        f"RMSE para K_W = 0: "
        f"{RMSE_zero:.8e}"
    )

    print(
        f"R² para K_W = 0: "
        f"{R2_zero:.6f}"
    )

    print(
        f"CE final para K_W = 0: "
        f"{CE_zero:.8f} mol L^-1"
    )

    print("\nVariação relativa do RMSE:")

    for i in range(len(resultados)):

        print(
            f"K_W = {resultados[i,0]:.4f}"
            f" → "
            f"{variacao_RMSE[i]:.4f}%"
        )

    print("\nVariação relativa de CE final:")

    for i in range(len(resultados)):

        print(
            f"K_W = {resultados[i,0]:.4f}"
            f" → "
            f"{variacao_CE_final[i]:.4f}%"
        )

    return (
        resultados,
        curvas,
        variacao_RMSE,
        variacao_CE_final
    )


