import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import r2_score

# dados
x = np.array([0.000872, 0.000967, 0.00079, 0.001324, 0.001018, 0.00122, 0.001634, 0.005109, 0.005619])
y = np.array([0.000876, 0.000967, 0.000794, 0.001779, 0.001007, 0.001533, 0.002177, 0.005075, 0.005696])

# R²
r2 = r2_score(x, y)

plt.figure(figsize=(6,6))

# pontos
plt.scatter(x, y, s=70)

# linha y=x
min_val = min(x.min(), y.min())
max_val = max(x.max(), y.max())
plt.plot([min_val, max_val], [min_val, max_val], linewidth=2)

# eixo 1:1
plt.xlim(min_val*0.95, max_val*1.05)
plt.ylim(min_val*0.95, max_val*1.05)
plt.gca().set_aspect('equal', adjustable='box')

# labels
plt.xlabel("Método de busca - Otimização ", fontsize=12)
plt.ylabel("Método de busca – Heurístico (Algoritmo de Abelhas)", fontsize=12)

# grade
plt.grid(True, linestyle="--", alpha=0.5)

# mostrar R2
plt.text(min_val*1.1, max_val*0.9, f"$R^2$ = {r2:.4f}", fontsize=12)

plt.tight_layout()
plt.show()

import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import r2_score

# dados base
x = np.array([0.000872, 0.000967, 0.00079, 0.001324, 0.001018, 0.00122, 0.001634, 0.005109, 0.005619])

# Python
y_python = np.array([0.000876, 0.000967, 0.000794, 0.001779, 0.001007, 0.001533, 0.002177, 0.005075, 0.005696])

# R
y_r = np.array([0.001656, 0.000967, 0.000791, 0.001775, 0.001015, 0.001552, 0.002181, 0.005122, 0.00572])

# Scilab
y_scilab = np.array([0.0008742929, 0.0009667407, 0.0007910054, 0.0017750244, 0.0010154396, 0.001552, 0.0021811363, 0.0051226, 0.005719])

# R2
r2_python = r2_score(x, y_python)
r2_r = r2_score(x, y_r)
r2_scilab = r2_score(x, y_scilab)

plt.figure(figsize=(6,6))

# pontos
plt.scatter(x, y_python, s=70, label=f"Python (R² = {r2_python:.4f})")
plt.scatter(x, y_r, s=70, label=f"R (R² = {r2_r:.4f})")
plt.scatter(x, y_scilab, s=70, label=f"Scilab (R² = {r2_scilab:.4f})")

# linha identidade
min_val = min(x.min(), y_python.min(), y_r.min(), y_scilab.min())
max_val = max(x.max(), y_python.max(), y_r.max(), y_scilab.max())

plt.plot([min_val, max_val], [min_val, max_val], linewidth=2)

# eixo 1:1
plt.xlim(min_val*0.95, max_val*1.05)
plt.ylim(min_val*0.95, max_val*1.05)
plt.gca().set_aspect('equal', adjustable='box')

# labels
plt.xlabel("Otimização pelo gradiente", fontsize=12)
plt.ylabel("Heurístico (ABC)", fontsize=12)

# grade
plt.grid(True, linestyle="--", alpha=0.5)

# legenda
plt.legend()

plt.tight_layout()
plt.show()

