import numpy as np
from scipy.optimize import minimize

# Dados
T = np.array([351.15, 356.15, 361.15, 366.15])

k_ap = np.array([0.00198726, 0.00238713, 0.00262844, 0.00260894])
k_int = np.array([0.02277213, 0.02393224, 0.03035715, 0.03087485])

R = 8.314  # J/mol.K

# Variável independente
x = 1 / T
y_ap = np.log(k_ap)
y_int = np.log(k_int)

# Função objetivo: mesmo slope, interceptos diferentes
def objective(params):
    slope, b_ap, b_int = params

    y_ap_pred = slope * x + b_ap
    y_int_pred = slope * x + b_int

    error = np.sum((y_ap - y_ap_pred)**2) + np.sum((y_int - y_int_pred)**2)
    return error

# chute inicial
init = [-1000, 0, 0]

res = minimize(objective, init)

