import numpy as np
import matplotlib.pyplot as plt
from scipy.stats import linregress
from scipy.optimize import minimize

# ======================
# Dados
# ======================
T = np.array([351.15, 356.15, 361.15, 366.15])

k_ap = np.array([0.00198726, 0.00238713, 0.00262844, 0.00260894])
k_int = np.array([0.02277213, 0.02393224, 0.03035715, 0.03087485])

R = 8.314

x = 1 / T
y_ap = np.log(k_ap)
y_int = np.log(k_int)

# ======================
# Ajustes individuais
# ======================
slope_ap, intercept_ap, r_ap, _, _ = linregress(x, y_ap)
slope_int, intercept_int, r_int, _, _ = linregress(x, y_int)

# ======================
# Ajuste conjunto (mesma Ea)
# ======================
def objective(params):
    slope, b_ap, b_int = params
    err = np.sum((y_ap - (slope*x + b_ap))**2)
    err += np.sum((y_int - (slope*x + b_int))**2)
    return err

res = minimize(objective, [-1000, 0, 0])
slope_c, b_ap_c, b_int_c = res.x

# R² conjunto
def calc_r2(y, y_pred):
    return 1 - np.sum((y - y_pred)**2) / np.sum((y - np.mean(y))**2)

r2_ap_c = calc_r2(y_ap, slope_c*x + b_ap_c)
r2_int_c = calc_r2(y_int, slope_c*x + b_int_c)

# ======================
# Plot
# ======================
x_plot = np.linspace(x.min(), x.max(), 100)

plt.figure(figsize=(8,6))

# Pontos
plt.scatter(x, y_ap, label='k aparente')
plt.scatter(x, y_int, label='k intrínseco')

# Ajustes individuais
plt.plot(x_plot, slope_ap*x_plot + intercept_ap,
         linestyle='--',
         label=f'Ajuste ap (R²={r_ap**2:.4f})')

plt.plot(x_plot, slope_int*x_plot + intercept_int,
         linestyle='--',
         label=f'Ajuste int (R²={r_int**2:.4f})')

# Ajuste conjunto
plt.plot(x_plot, slope_c*x_plot + b_ap_c,
         linestyle='-',
         label=f'Conjunto ap (R²={r2_ap_c:.4f})')

plt.plot(x_plot, slope_c*x_plot + b_int_c,
         linestyle='-',
         label=f'Conjunto int (R²={r2_int_c:.4f})')

# Labels
plt.xlabel('1/T (K⁻¹)')
plt.ylabel('ln(k)')
plt.title('Ajuste de Arrhenius')
plt.legend()
plt.grid()

plt.show()

